import json, os
from app import AuditChain, ZERO
c = AuditChain("/tmp/definitely-never-created.jsonl")
def row(tenant="t", seq=1, prev=ZERO, event=None):
    item = {"tenant": tenant, "seq": seq, "event": event or {}, "prev": prev}
    item["hash"] = AuditChain._hash(item)
    return (json.dumps(item, sort_keys=True, allow_nan=False) + "\n").encode()
rec = row()
# one-shot generator + split mid-record vs empty side -> missing_left
r = c.compare_chunks(iter([rec[:13], rec[13:]]), [])
print(r["equal"], r["tenant"], r["reason"], r["left"] is None, r["right"]["seq"])
# right bad element beats left corrupt content
try:
    c.compare_chunks([b"{oops\n"], [b"", 1])
except ValueError as e:
    print("ValueError:", e)
# left bare bytes wins; right iterator never touched
class Probe:
    def __iter__(self): raise AssertionError("touched")
try:
    c.compare_chunks(b"bare", Probe())
except ValueError as e:
    print("ValueError:", e)
# identical streams split per-byte -> equal
data = row()
print(c.compare_chunks([bytes([b]) for b in data], (b for b in [data]))["equal"])
print("phantom exists:", os.path.exists("/tmp/definitely-never-created.jsonl"))
